// Package db is energyd's ledger store: SQLite with squibble migrations against
// the embedded schema.sql and typed queries generated by sqlc into db/dbsqlc.
package db

import (
	"context"
	"database/sql"
	_ "embed"
	"errors"
	"fmt"
	"os"
	"time"

	"github.com/juanfont/headscale/hscontrol/db/sqliteconfig"
	"github.com/tailscale/squibble"
	_ "modernc.org/sqlite" // pure-Go driver, registered as "sqlite"

	"energyd/db/dbsqlc"
)

//go:embed schema.sql
var dbSchema string

// IgnoreTables keeps litestream's bookkeeping tables out of the schema digest:
// litestream creates them at runtime, and squibble would refuse them as drift.
var schema = &squibble.Schema{
	Current:      dbSchema,
	IgnoreTables: []string{"_litestream_seq", "_litestream_lock"},
}

// DB is the ledger store. Reads go through the embedded generated queries.
type DB struct {
	*dbsqlc.Queries

	sql *sql.DB
}

// Open opens (creating if needed) the database at path and applies migrations.
func Open(ctx context.Context, path string) (*DB, error) {
	// Litestream runs as another user in the owner's group and writes to these
	// files. SQLite creates them group read-only under the service's umask, and
	// -wal and -shm copy the main file's mode, so the main file comes first.
	file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o660)
	if err != nil {
		return nil, fmt.Errorf("create database file: %w", err)
	}

	if err := file.Close(); err != nil {
		return nil, fmt.Errorf("create database file: %w", err)
	}

	uri, err := sqliteconfig.Default(path).ToURL()
	if err != nil {
		return nil, fmt.Errorf("build sqlite uri: %w", err)
	}

	sqlDB, err := sql.Open("sqlite", uri)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}

	if err := schema.Apply(ctx, sqlDB); err != nil {
		_ = sqlDB.Close()

		return nil, fmt.Errorf("apply schema: %w", err)
	}

	return &DB{Queries: dbsqlc.New(sqlDB), sql: sqlDB}, nil
}

// LoadLogin returns saved login state, or zero times when there is none.
func (d *DB) LoadLogin(ctx context.Context) (lastAttempt, blockedUntil time.Time, err error) {
	row, err := d.GetLoginState(ctx)
	if errors.Is(err, sql.ErrNoRows) {
		return time.Time{}, time.Time{}, nil
	}

	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("login state: %w", err)
	}

	return fromUnix(row.LastAttempt), fromUnix(row.BlockedUntil), nil
}

// SaveLogin stores login state. A zero time means none.
func (d *DB) SaveLogin(ctx context.Context, lastAttempt, blockedUntil time.Time) error {
	return d.UpsertLoginState(ctx, dbsqlc.UpsertLoginStateParams{
		LastAttempt:  toUnix(lastAttempt),
		BlockedUntil: toUnix(blockedUntil),
	})
}

func toUnix(t time.Time) int64 {
	if t.IsZero() {
		return 0
	}

	return t.Unix()
}

func fromUnix(v int64) time.Time {
	if v == 0 {
		return time.Time{}
	}

	return time.Unix(v, 0)
}

// Close closes the underlying database.
func (d *DB) Close() error { return d.sql.Close() }

// Tx runs fn in one transaction, so a day and its hours land together.
func (d *DB) Tx(ctx context.Context, fn func(q *dbsqlc.Queries) error) error {
	tx, err := d.sql.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin tx: %w", err)
	}
	defer tx.Rollback() //nolint:errcheck // rollback after commit is a no-op

	if err := fn(d.WithTx(tx)); err != nil {
		return err
	}

	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit: %w", err)
	}

	return nil
}
